import java.util.Scanner;

public class Main {
    static String s;
    static int len;
    static int n;

    static boolean check(int a) {
        for (int i = 1; i <= a - n; i++) {
            if (s.charAt(len - i) != s.charAt(len - i - a)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        s = scanner.next();
        len = s.length();
        n = scanner.nextInt();

        int min, max;
        if (n > len) {
            min = (len + n) / 2;
        } else {
            min = n;
        }
        max = (len + n) / 2;

        int temp = 0;
        for (int i = 0; i < len; i++) {
            for (int j = 1; j * 2 + i <= len; j++) {
                boolean key = true;
                for (int k = 1; k <= j; k++) {
                    if (s.charAt(i + k - 1) != s.charAt(i + k + j - 1)) {
                        key = false;
                        break;
                    }
                }
                if (key && j > temp) {
                    temp = j;
                }
            }
        }

        int ans = 0;
        for (int i = max; i >= min && ans == 0; i--) {
            if (check(i)) {
                ans = i;
            }
        }
        if (min > ans) {
            ans = min;
        }
        if (temp > ans) {
            ans = temp;
        }
        System.out.print(2 * ans);
    }
}

